70	    publish(value) {
71	        const catalog = validateAgentModelCatalog(value);
72	        this.catalogs.set(catalog.agent, catalog);
73	        this.dispatchEvent(new CustomEvent('catalog', { detail: catalog }));
74	
75	        return catalog;
76	    }
77	
78	    async stop() {
79	        for (const probe of this.activeProbes) await probe.close();
80	        this.activeProbes.clear();
81	    }
82	}
