8	/** Subscribe to the shared model list for an agent; only explicit refresh performs discovery. */
9	export function useAgentModelCatalog(
10	    profile: AgentProfile | null,
11	    service: AgentCapabilitiesService = agentCapabilitiesService,
12	) {
13	    const key = profile?.name ?? '';
14	    const snapshot = useSyncExternalStore(
15	        (onStoreChange) => {
16	            service.addEventListener(`catalog:${key}`, onStoreChange);
17	
18	            return () => service.removeEventListener(`catalog:${key}`, onStoreChange);
19	        },
20	        () => service.getCatalogSnapshot(key),
21	        () => service.getCatalogSnapshot(key),
22	    );
23	    useEffect(() => {
24	        if (profile && !snapshot.loading && !snapshot.error && !snapshot.catalog) {
25	            void service.loadCatalog(profile);
26	        }
27	    }, [key, profile, service, snapshot]);
28	    const refresh = useCallback(async () => {
29	        if (profile) await service.loadCatalog(profile, true);
30	    }, [profile, service]);
31	
32	    return { ...snapshot, refresh };
33	}
